const input = items[0].json || {};
const recipient = String(input.recipient || '').trim();
const subject = String(input.subject || 'Document').trim();
const body = String(input.body || '').trim();
const drive_file_id = String(input.drive_file_id || input.file_id || '').trim();
const requestBody = JSON.stringify({ subject, body: { contentType: 'Text', content: body }, toRecipients: [{ emailAddress: { address: recipient } }] });
return [{ json: { ...input, recipient, subject, body, drive_file_id, requestBody, graphUrl: 'https://graph.microsoft.com/v1.0/me/messages' } }];

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function safeText(value) {
  return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
function person(mailbox) {
  const e = mailbox?.emailAddress || mailbox || {};
  return { name: e.name || '', email: e.address || '' };
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

const input = $('Prepare Graph Request').item.json;
const d = items[0].json || {};
if (d.error || !d.id) return fail('WF_CREATE_OUTLOOK_DRAFT_WITH_ONEDRIVE_ATTACHMENT', d.error || d.message || 'Draft was not created');
return pass(`Draft created: Yes\nRecipient: ${input.recipient}\nSubject: ${input.subject}\nAttachment source: OneDrive file ID ${input.drive_file_id}\nDraft link if available: ${d.webLink || ''}\nEmail sent: No\nVerification status: Passed`, { draft_id: d.id, drive_file_id: input.drive_file_id, attachmentStep: 'Select/add attachment node after import if binary attachment is required.', emailSent: false });
